import React from 'react';
import Chatbot from './Chatbot';

const RecruiterChat = ({ token }) => {
  return (
    <div>
      <p className="muted" style={{ marginTop: 0 }}>
        Ask questions across the entire applicant corpus, like "Who has strong React and AWS?" or "Any Python data engineers?".
      </p>
      <Chatbot token={token} mode="corpus" />
    </div>
  );
};

export default RecruiterChat;
